import Foundation

/// Decodes `nav.json` — the shared navigation manifest — into `WebTab`s.
///
/// The manifest is generated by `scripts/gen-nav-manifest.mjs` from `SECTIONS`
/// in `site/erp.html`, with every label resolved through the same dictionary
/// the web app uses. It is the ONE place tab names live; this file only reads
/// it. See the note on `Config.tabs` for what it replaced and why.
enum NavManifest {
    private struct Root: Decodable {
        let version: Int
        let tabs: [Tab]
    }

    private struct Tab: Decodable {
        let id: String
        let path: String
        let icon: String
        let label: [String: String]
    }

    /// The bundled manifest, in `Config.uiLanguage`.
    ///
    /// Falls back to the previous hardcoded set if the file is missing or
    /// unreadable. That fallback is deliberate and is NOT a second source of
    /// truth: an app with no tab bar is unusable, and a decode failure means a
    /// packaging mistake, which should degrade to the last known-good layout
    /// rather than to a blank screen. `navManifestLoaded` records which path
    /// was taken so a packaging mistake is visible rather than silent.
    static func load() -> [WebTab] {
        guard
            let url = Bundle.main.url(forResource: "nav", withExtension: "json"),
            let data = try? Data(contentsOf: url),
            let root = try? JSONDecoder().decode(Root.self, from: data),
            root.version == 1,
            !root.tabs.isEmpty
        else {
            navManifestLoaded = false
            return fallback
        }

        let lang = Config.uiLanguage
        navManifestLoaded = true
        return root.tabs.map { tab in
            WebTab(
                id: tab.id,
                // Spanish is the hub everywhere else in this product, so it is
                // the last resort here too — never an empty tab.
                title: tab.label[lang] ?? tab.label["es"] ?? tab.id,
                systemImage: tab.icon,
                path: tab.path
            )
        }
    }

    /// True when the tab bar came from the manifest. Read by the diagnostics
    /// screen; a `false` here means the app shipped without `nav.json`.
    private(set) static var navManifestLoaded = false

    /// Last known-good layout, used only when the manifest cannot be read.
    ///
    /// English because that is what this list has always been; it is a
    /// break-glass copy, not a translation.
    private static let fallback: [WebTab] = [
        WebTab(id: "tower", title: "Tower",
               systemImage: "chart.bar.xaxis.ascending", path: "erp.html#tower"),
        WebTab(id: "sales", title: "Commercial",
               systemImage: "person.2.fill", path: "erp.html#leads"),
        WebTab(id: "projects", title: "Projects",
               systemImage: "square.stack.3d.up.fill", path: "erp.html#progress"),
        WebTab(id: "admin", title: "Admin",
               systemImage: "eurosign.circle.fill", path: "erp.html#invoicing"),
        WebTab(id: "master-data", title: "Master data",
               systemImage: "square.grid.2x2.fill", path: "erp.html#customers"),
        WebTab(id: "settings", title: "Settings",
               systemImage: "gearshape.fill", path: "erp.html#users"),
    ]
}
